    boxShadow: "0 4px 20px rgba(0,0,0,0.2)",
    fontSize: "0.9rem",
    fontWeight: 500,
  },
  modalOverlay: {
    position: "fixed",
    inset: 0,
    background: "rgba(0,0,0,0.5)",
