    borderRadius: "50%",
    background: "#ffeaea",
    color: "#e74c3c",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    marginBottom: "1rem",
  },
  deleteConfirmBtn: {
    display: "flex",
    alignItems: "center",
    gap: "6px",
    padding: "12px 20px",
    background: "#e74c3c",
    color: "white",
    border: "none",
    borderRadius: "6px",
    fontWeight: 600,
    cursor: "pointer",
    fontSize: "0.9rem",
  },
  adminLoginHeader: {
    display: "flex",
    alignItems: "center",
    gap: "12px",
    marginBottom: "0.5rem",
  },
  adminIconBig: {
    width: "40px",
    height: "40px",
    borderRadius: "50%",
    background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
    color: "white",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  loginForm: {
    display: "flex",
    flexDirection: "column",
    gap: "0.5rem",
  },
  loginError: {
    display: "flex",
    alignItems: "center",
    gap: "8px",
    padding: "10px 14px",
    background: "#ffeaea",
    color: "#e74c3c",
    borderRadius: "6px",
    fontSize: "0.9rem",
    marginBottom: "1rem",
  },
  adminLoginBtn: {
    display: "flex",
    alignItems: "center",
    gap: "6px",
    padding: "12px 20px",
    background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
    color: "white",
    border: "none",
    borderRadius: "6px",
    fontWeight: 600,
    cursor: "pointer",
    fontSize: "0.9rem",
  },
  nav: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "1rem 3rem",
    background: "rgba(247,243,237,0.95)",
    backdropFilter: "blur(10px)",
    position: "sticky",
    top: 0,
    zIndex: 100,
    borderBottom: "1px solid rgba(0,0,0,0.05)",
  },
  logo: {
    fontFamily: "'Cormorant Garamond', Georgia, serif",
    fontSize: "1.6rem",
    fontWeight: 700,
    color: "#2C2C2C",
    textDecoration: "none",
    cursor: "pointer",
    userSelect: "none",
  },
  logoAccent: {
    color: "#C4704F",
  },
  navLinks: {
    display: "flex",
    alignItems: "center",
    gap: "1.5rem",
  },
  navLink: {
    color: "#5A5A5A",
    textDecoration: "none",
    fontSize: "0.9rem",
    fontWeight: 500,
    cursor: "pointer",
    display: "flex",
    alignItems: "center",
    gap: "4px",
  },
  badge: {
    background: "#C4704F",
    color: "white",
    fontSize: "0.7rem",
    padding: "2px 6px",
    borderRadius: "10px",
    fontWeight: 600,
  },
  createBtn: {
    display: "flex",
    alignItems: "center",
    gap: "6px",
    padding: "10px 20px",
    background: "#C4704F",
    color: "white",
    border: "none",
    borderRadius: "6px",
    fontSize: "0.9rem",
    fontWeight: 600,
    cursor: "pointer",
  },
  userButton: {
    display: "flex",
    alignItems: "center",
    gap: "8px",
    padding: "8px 16px",
    background: "white",
    border: "1px solid #ddd",
    borderRadius: "8px",
    cursor: "pointer",
    fontSize: "14px",
    fontWeight: 500,
    color: "#333",
    transition: "all 0.2s",
  },
  userAvatar: {
    width: "28px",
    height: "28px",
    borderRadius: "50%",
    objectFit: "cover",
  },
  userName: {
    maxWidth: "100px",
    overflow: "hidden",
    textOverflow: "ellipsis",
    whiteSpace: "nowrap",
  },
  signInText: {
    fontSize: "14px",
  },
  dropdownContainer: {
    position: "relative",
    display: "inline-block",
  },
  dropdown: {
    position: "absolute",
    top: "100%",
    right: 0,
    width: "280px",
