const styleSheet = document.createElement("style");
styleSheet.textContent = `
  @import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;0,700;1,400&family=DM+Sans:ital,wght@0,400;0,500;0,700;1,400&display=swap');
  
  @keyframes spin {
    to { transform: rotate(360deg); }
  }
  
  @keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
  }
  
  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(-20px); }
    to { opacity: 1; transform: translateY(0); }
  }
  
  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }
  
  body {
    font-family: 'DM Sans', -apple-system, sans-serif;
  }
  
  button {
    font-family: inherit;
  }
  
  input, textarea, select {
    font-family: inherit;
  }
  
  article:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 30px rgba(0,0,0,0.12) !important;
  }
  
  article:hover img {
    transform: scale(1.05);
  }
  
  article:hover .storyOverlay {
    opacity: 1 !important;
  }
  
  button:hover {
    opacity: 0.9;
  }
  
  a:hover {
    color: #C4704F !important;
  }
  
  input:focus, textarea:focus, select:focus {
    border-color: #C4704F !important;
  }
  
  .divider::before {
    content: "";
    position: absolute;
    top: 50%;
    left: 0;
    right: 0;
    height: 1px;
    background-color: #eee;
    z-index: 0;
  }
  
  @media (max-width: 1024px) {
    .hero {
      grid-template-columns: 1fr !important;
      gap: 2rem !important;
    }
    
    .heroImage {
      height: 400px !important;
